__device__ __forceinline__ float block_sum_leader(
    float value, float* warp_sums) {
  for (int offset = 16; offset > 0; offset >>= 1) {
    value += __shfl_down_sync(0xffffffff, value, offset);
  }
  const int lane = static_cast<int>(threadIdx.x) & 31;
  const int warp = static_cast<int>(threadIdx.x) >> 5;
  if (lane == 0) {
    warp_sums[warp] = value;
  }
  __syncthreads();
  if (warp == 0) {
    value = lane < (static_cast<int>(blockDim.x) + 31) / 32
        ? warp_sums[lane]
        : 0.0f;
    for (int offset = 16; offset > 0; offset >>= 1) {
      value += __shfl_down_sync(0xffffffff, value, offset);
    }
  }
  return value;
}

__global__ void panel_qr_wy_kernel(
    const float* input, float* output_v, float* output_t,
    int rows, int width) {
  extern __shared__ float shared[];
  float* matrix = shared;
  const int pitch = width + 1;
  float* t = matrix + rows * pitch;
  float* coefficients = t + width * width;
  float* transformed = coefficients + width;
  float* reduction = transformed + width;
  const int tid = static_cast<int>(threadIdx.x);
  const int lane = tid & 31;
  const int warp = tid >> 5;
  const int warp_count = static_cast<int>(blockDim.x) >> 5;
  const int64_t panel_offset =
      static_cast<int64_t>(blockIdx.x) * rows * width;
  const int64_t triangular_offset =
      static_cast<int64_t>(blockIdx.x) * width * width;

  for (int index = tid; index < rows * width; index += blockDim.x) {
    const int row = index / width;
    const int column = index - row * width;
    matrix[row * pitch + column] = input[panel_offset + index];
  }
  for (int index = tid; index < width * width; index += blockDim.x) {
    t[index] = 0.0f;
  }
  __syncthreads();

  for (int column = 0; column < width; ++column) {
    float local_norm = 0.0f;
    for (int row = column + 1 + tid; row < rows; row += blockDim.x) {
      const float value = matrix[row * pitch + column];
      local_norm += value * value;
    }
    const float norm_sum = block_sum_leader(local_norm, reduction);
    if (tid == 0) {
      const float alpha = matrix[column * pitch + column];
      const float tail_norm = sqrtf(norm_sum);
      float beta = alpha;
      float tau = 0.0f;
      float inverse = 0.0f;
      if (tail_norm != 0.0f) {
        beta = -copysignf(hypotf(alpha, tail_norm), alpha);
        tau = (beta - alpha) / beta;
        inverse = 1.0f / (alpha - beta);
      }
      matrix[column * pitch + column] = beta;
      t[column * width + column] = tau;
      reduction[0] = tau;
      reduction[1] = inverse;
    }
    __syncthreads();

    const float tau = reduction[0];
    const float inverse = reduction[1];
    for (int row = column + 1 + tid; row < rows; row += blockDim.x) {
      matrix[row * pitch + column] *= inverse;
    }
    __syncthreads();

    for (int target = column + 1 + warp; target < width;
         target += warp_count) {
      float partial = 0.0f;
      for (int row = column + lane; row < rows; row += 32) {
        const float reflector = row == column
            ? 1.0f
            : matrix[row * pitch + column];
        partial += reflector * matrix[row * pitch + target];
      }
      for (int offset = 16; offset > 0; offset >>= 1) {
        partial += __shfl_down_sync(0xffffffff, partial, offset);
      }
      const float dot = tau * __shfl_sync(0xffffffff, partial, 0);
      for (int row = column + lane; row < rows; row += 32) {
        const float reflector = row == column
            ? 1.0f
            : matrix[row * pitch + column];
        matrix[row * pitch + target] -= reflector * dot;
      }
    }
    __syncthreads();
  }

  for (int column = 1; column < width; ++column) {
    const float tau = t[column * width + column];
    for (int previous = tid; previous < column;
         previous += blockDim.x) {
      float overlap = 0.0f;
      for (int row = column; row < rows; ++row) {
        const float current = row == column
            ? 1.0f
            : matrix[row * pitch + column];
        overlap += matrix[row * pitch + previous] * current;
      }
      coefficients[previous] = -tau * overlap;
    }
    __syncthreads();
    for (int row = tid; row < column; row += blockDim.x) {
      float sum = 0.0f;
      for (int inner = 0; inner < column; ++inner) {
        sum += t[row * width + inner] * coefficients[inner];
      }
      transformed[row] = sum;
    }
    __syncthreads();
    for (int row = tid; row < column; row += blockDim.x) {
      t[row * width + column] = transformed[row];
    }
    __syncthreads();
  }

  for (int index = tid; index < rows * width; index += blockDim.x) {
    const int row = index / width;
    const int column = index - row * width;
    output_v[panel_offset + index] = row < column
        ? 0.0f
        : (row == column ? 1.0f : matrix[row * pitch + column]);
  }
  for (int index = tid; index < width * width; index += blockDim.x) {
    output_t[triangular_offset + index] = t[index];
  }
}

__global__ void compact_wy_t_kernel(
    const float* gram, const float* taus, float* output, int width) {
  extern __shared__ float shared[];
  float* t = shared;
  float* coefficients = t + width * width;
  float* transformed = coefficients + width;
  const int tid = static_cast<int>(threadIdx.x);
  const int64_t matrix_offset =
      static_cast<int64_t>(blockIdx.x) * width * width;
  const int64_t vector_offset = static_cast<int64_t>(blockIdx.x) * width;

  for (int index = tid; index < width * width; index += blockDim.x) {
    t[index] = 0.0f;
  }
  __syncthreads();

  for (int column = 0; column < width; ++column) {
    if (tid < column) {
      coefficients[tid] = -taus[vector_offset + column] *
          gram[matrix_offset + tid * width + column];
    }
    __syncthreads();
    if (tid < column) {
      float sum = 0.0f;
      for (int inner = tid; inner < column; ++inner) {
        sum += t[tid * width + inner] * coefficients[inner];
      }
      transformed[tid] = sum;
    }
    __syncthreads();
    if (tid < column) {
      t[tid * width + column] = transformed[tid];
    } else if (tid == column) {
      t[column * width + column] = taus[vector_offset + column];
    }
    __syncthreads();
  }

  for (int index = tid; index < width * width; index += blockDim.x) {
    output[matrix_offset + index] = t[index];
  }
}

__global__ void reduce_band_to_tridiagonal(
    const float* input, float* reflectors, float* diagonal, float* off_diagonal,
    float* taus, int n) {
  extern __shared__ float shared[];
  float* matrix = shared;
  const int pitch = n + 4;
  float* v = matrix + n * pitch;
  float* y = v + n;
  float* reduction = y + n;
  const int tid = static_cast<int>(threadIdx.x);
  const int64_t batch_offset = static_cast<int64_t>(blockIdx.x) * n * n;

  const int load_warp = tid >> 5;
  const int load_lane = tid & 31;
  for (int row = load_warp; row < n; row += blockDim.x >> 5) {
    for (int col = load_lane; col <= row; col += 32) {
      matrix[row * pitch + col] = input[batch_offset + row * n + col];
    }
  }
  __syncthreads();

  for (int column = 0; column < n - 2; ++column) {
    const int base = column + 1;
    const int size = n - base;
    float local_norm = 0.0f;
    for (int index = tid + 1; index < size; index += blockDim.x) {
      const float value = matrix[(base + index) * pitch + column];
      local_norm += value * value;
    }
    const float norm_sum = block_sum_leader(local_norm, reduction);

    if (tid == 0) {
      const float alpha = matrix[base * pitch + column];
      const float tail_norm = sqrtf(norm_sum);
      float beta = alpha;
      float tau = 0.0f;
      float inverse = 0.0f;
      if (tail_norm != 0.0f) {
        beta = -copysignf(hypotf(alpha, tail_norm), alpha);
        tau = (beta - alpha) / beta;
        inverse = 1.0f / (alpha - beta);
      }
      diagonal[static_cast<int64_t>(blockIdx.x) * n + column] =
          matrix[column * pitch + column];
      off_diagonal[static_cast<int64_t>(blockIdx.x) * n + column] = beta;
      taus[static_cast<int64_t>(blockIdx.x) * n + column] = tau;
      reduction[0] = tau;
      reduction[1] = inverse;
    }
    __syncthreads();

    const float tau = reduction[0];
    const float inverse = reduction[1];
    for (int index = tid; index < size; index += blockDim.x) {
      v[index] = index == 0
          ? 1.0f
          : matrix[(base + index) * pitch + column] * inverse;
    }
    __syncthreads();

    constexpr int kDotWidth = 4;
    const int row = tid / kDotWidth;
    const int dot_lane = tid & (kDotWidth - 1);
    float local_dot = 0.0f;
    if (row < size) {
      float sum = 0.0f;
      for (int inner = dot_lane; inner < size; inner += kDotWidth) {
        const float element = row >= inner
            ? matrix[(base + row) * pitch + base + inner]
            : matrix[(base + inner) * pitch + base + row];
        sum += element * v[inner];
      }
      const unsigned int mask = __activemask();
      sum += __shfl_down_sync(mask, sum, 2, kDotWidth);
      sum += __shfl_down_sync(mask, sum, 1, kDotWidth);
      if (dot_lane == 0) {
        const float y_value = tau * sum;
        y[row] = y_value;
        local_dot = v[row] * y_value;
      }
    }
    const float dot = block_sum_leader(local_dot, reduction);
    if (tid == 0) {
      reduction[0] = dot * (-0.5f * tau);
    }
    __syncthreads();
    const float correction = reduction[0];

    const int update_warp = tid >> 5;
    const int update_lane = tid & 31;
    for (int row = update_warp; row < size; row += blockDim.x >> 5) {
      const float row_v = v[row];
      const float row_y = y[row] + (2.0f * correction) * row_v;
      for (int col = update_lane; col <= row; col += 32) {
        matrix[(base + row) * pitch + base + col] -=
            row_v * y[col] + row_y * v[col];
      }
    }

    for (int index = tid; index < size; index += blockDim.x) {
      const float stored = index == 0
          ? off_diagonal[static_cast<int64_t>(blockIdx.x) * n + column]
          : v[index];
      reflectors[batch_offset + column * n + base + index] = stored;
    }
    __syncthreads();
  }

  if (tid == 0) {
    const int64_t vector_offset = static_cast<int64_t>(blockIdx.x) * n;
    diagonal[vector_offset + n - 2] = matrix[(n - 2) * pitch + n - 2];
    diagonal[vector_offset + n - 1] = matrix[(n - 1) * pitch + n - 1];
    off_diagonal[vector_offset + n - 2] =
        matrix[(n - 1) * pitch + n - 2];
    off_diagonal[vector_offset + n - 1] = 0.0f;
    taus[vector_offset + n - 2] = 0.0f;
    taus[vector_offset + n - 1] = 0.0f;
  }
}

__device__ __forceinline__ int packed_lower_index(int row, int column) {
  return (row * (row + 1)) / 2 + column;
}

template <bool kPackedLower>
__device__ __forceinline__ int matrix_lower_index(
    int row, int column, int n) {
  return kPackedLower ? packed_lower_index(row, column) : row * n + column;
}

__global__ void fused_householder_eigh32(
    const float* input, float* vectors, float* values) {
  constexpr int n = 32;
  constexpr int pitch = 36;
  constexpr int kGroupWidth = 8;
  constexpr int kSolveThreads = n * kGroupWidth;
  constexpr int kVectorPitch = 36;
  extern __shared__ float shared[];
  float* matrix = shared;
  float* v = matrix + n * pitch;
  float* y = v + n;
  float* reduction = y + n;
  float* reflectors = reduction + 256;
  float* d = reflectors + n * n;
  float* e = d + n;
  float* taus = e + n;
  float* eigenvectors = taus + n;
  float* factors = eigenvectors + n * kVectorPitch;

  const int tid = static_cast<int>(threadIdx.x);
  const int64_t batch_offset =
      static_cast<int64_t>(blockIdx.x) * n * n;
  const int load_warp = tid >> 5;
  const int load_lane = tid & 31;
  for (int row = load_warp; row < n; row += blockDim.x >> 5) {
    for (int column = load_lane; column <= row; column += 32) {
      matrix[row * pitch + column] =
          input[batch_offset + row * n + column];
    }
  }
  __syncthreads();

  for (int column = 0; column < n - 2; ++column) {
    const int base = column + 1;
    const int size = n - base;
    float local_norm = 0.0f;
    for (int index = tid + 1; index < size; index += blockDim.x) {
      const float value = matrix[(base + index) * pitch + column];
      local_norm += value * value;
    }
    if (tid < 32) {
      for (int offset = 16; offset > 0; offset >>= 1) {
        local_norm += __shfl_down_sync(0xffffffff, local_norm, offset);
      }
    }

    if (tid == 0) {
      const float alpha = matrix[base * pitch + column];
      const float tail_norm = sqrtf(local_norm);
      float beta = alpha;
      float tau = 0.0f;
      float inverse = 0.0f;
      if (tail_norm != 0.0f) {
        beta = -copysignf(hypotf(alpha, tail_norm), alpha);
        tau = (beta - alpha) / beta;
        inverse = 1.0f / (alpha - beta);
      }
      d[column] = matrix[column * pitch + column];
      e[column] = beta;
      taus[column] = tau;
      reduction[0] = tau;
      reduction[1] = inverse;
    }
    __syncthreads();

    const float tau = reduction[0];
    const float inverse = reduction[1];
    for (int index = tid; index < size; index += blockDim.x) {
      v[index] = index == 0
          ? 1.0f
          : matrix[(base + index) * pitch + column] * inverse;
    }
    __syncthreads();

    constexpr int kDotWidth = 4;
    const int dot_row = tid / kDotWidth;
    const int dot_lane = tid & (kDotWidth - 1);
    float local_dot = 0.0f;
    if (dot_row < size) {
      float sum = 0.0f;
      for (int inner = dot_lane; inner < size; inner += kDotWidth) {
        const float element = dot_row >= inner
            ? matrix[(base + dot_row) * pitch + base + inner]
            : matrix[(base + inner) * pitch + base + dot_row];
        sum += element * v[inner];
      }
      const unsigned int mask = __activemask();
      sum += __shfl_down_sync(mask, sum, 2, kDotWidth);

      float cosine = 1.0f;
      float sine = 0.0f;
      if (fabsf(apq) > 2.0f * FLT_EPSILON *
              (fabsf(app) + fabsf(aqq) + FLT_MIN)) {
        const float tau = (aqq - app) / (2.0f * apq);
        const float tangent = copysignf(
            1.0f / (fabsf(tau) + sqrtf(fmaf(tau, tau, 1.0f))), tau);
        cosine = rsqrtf(1.0f + tangent * tangent);
        sine = tangent * cosine;
      }
      rotation_c[p] = cosine;
      rotation_c[q] = cosine;
      rotation_s[p] = -sine;
      rotation_s[q] = sine;
      rotation_mate[p] = q;
      rotation_mate[q] = p;
    }
    __syncthreads();

    const int column_mate = rotation_mate[column];
    const int row_mate = rotation_mate[row];
    const float column_c = rotation_c[column];
    const float column_s = rotation_s[column];
    const float row_c = rotation_c[row];
    const float row_s = rotation_s[row];
    const float own_row = fmaf(
        column_s, current_matrix[row * 32 + column_mate],
        column_c * current_matrix[tid]);
    const float mate_row = fmaf(
        column_s, current_matrix[row_mate * 32 + column_mate],
        column_c * current_matrix[row_mate * 32 + column]);
    next_matrix[tid] = fmaf(row_s, mate_row, row_c * own_row);
    next_vectors[tid] = fmaf(
        column_s, current_vectors[row * 32 + column_mate],
        column_c * current_vectors[tid]);
    __syncthreads();
    float* swap = current_matrix;
    current_matrix = next_matrix;
    next_matrix = swap;
    swap = current_vectors;
    current_vectors = next_vectors;
    next_vectors = swap;
  }

  if (tid < 32) {
    float keys[1] = {current_matrix[tid * 32 + tid]};
    int columns[1] = {tid};
    WarpSort(sort_storage).Sort(keys, columns, FloatLess{});
    values[static_cast<int64_t>(blockIdx.x) * 32 + tid] =
        keys[0] * output_scale;
    permutation[tid] = columns[0];
  }
  __syncthreads();
  vectors[matrix_offset + tid] =
      current_vectors[row * 32 + permutation[column]];
}

__global__ void pack_lower_triangle(
    const float* input, float* packed, int n) {
  const int tid = static_cast<int>(threadIdx.x);
  const int packed_size = n * (n + 1) / 2;
  const int64_t input_offset = static_cast<int64_t>(blockIdx.x) * n * n;
  const int64_t packed_offset =
      static_cast<int64_t>(blockIdx.x) * packed_size;
  for (int index = tid; index < packed_size; index += blockDim.x) {
    const int row = static_cast<int>(
        0.5f * (sqrtf(8.0f * static_cast<float>(index) + 1.0f) - 1.0f));
    const int column = index - packed_lower_index(row, 0);
    packed[packed_offset + index] = input[input_offset + row * n + column];
  }
}

__global__ void unpack_lower_triangle(
    const float* packed, float* output, int n) {
  const int tid = static_cast<int>(threadIdx.x);
  const int packed_size = n * (n + 1) / 2;
  const int64_t packed_offset =
      static_cast<int64_t>(blockIdx.x) * packed_size;
  const int64_t output_offset = static_cast<int64_t>(blockIdx.x) * n * n;
  for (int index = tid; index < packed_size; index += blockDim.x) {
    const int row = static_cast<int>(
        0.5f * (sqrtf(8.0f * static_cast<float>(index) + 1.0f) - 1.0f));
    const int column = index - packed_lower_index(row, 0);
    output[output_offset + row * n + column] =
        packed[packed_offset + index];
  }
}

__global__ void reduce_global_to_tridiagonal_dense(
    float* matrix, float* diagonal, float* off_diagonal, float* taus, int n) {
  extern __shared__ float shared[];
  float* v = shared;
  float* y = v + n;
  float* reduction = y + n;
  const int tid = static_cast<int>(threadIdx.x);
  const int64_t batch_offset = static_cast<int64_t>(blockIdx.x) * n * n;
  const int64_t vector_offset = static_cast<int64_t>(blockIdx.x) * n;

  for (int column = 0; column < n - 2; ++column) {
    const int base = column + 1;
    const int size = n - base;
    float local_norm = 0.0f;
    for (int index = tid + 1; index < size; index += blockDim.x) {
      const float value = matrix[batch_offset + (base + index) * n + column];
      local_norm += value * value;
    }
    const float norm_sum = block_sum_leader(local_norm, reduction);

    if (tid == 0) {
      const float alpha = matrix[batch_offset + base * n + column];
      const float tail_norm = sqrtf(norm_sum);
      float beta = alpha;
      float tau = 0.0f;
      float inverse = 0.0f;
      if (tail_norm != 0.0f) {
        beta = -copysignf(hypotf(alpha, tail_norm), alpha);
        tau = (beta - alpha) / beta;
        inverse = 1.0f / (alpha - beta);
      }
      diagonal[vector_offset + column] =
          matrix[batch_offset + column * n + column];
      off_diagonal[vector_offset + column] = beta;
      taus[vector_offset + column] = tau;
      reduction[0] = tau;
      reduction[1] = inverse;
    }
    __syncthreads();

    const float tau = reduction[0];
    const float inverse = reduction[1];
    for (int index = tid; index < size; index += blockDim.x) {
      v[index] = index == 0
          ? 1.0f
          : matrix[batch_offset + (base + index) * n + column] * inverse;
    }
    __syncthreads();

    constexpr int kDotWidth = 8;
    const int dot_group = tid / kDotWidth;
    const int dot_lane = tid & (kDotWidth - 1);
    for (int row = dot_group; row < size;
         row += static_cast<int>(blockDim.x) / kDotWidth) {
      float sum = 0.0f;
      for (int inner = dot_lane; inner < size; inner += kDotWidth) {
        const float element = row >= inner
            ? matrix[batch_offset + (base + row) * n + base + inner]
            : matrix[batch_offset + (base + inner) * n + base + row];
        sum += element * v[inner];
      }
      const unsigned int mask = __activemask();
      #pragma unroll
      for (int offset = kDotWidth / 2; offset > 0; offset >>= 1) {
        sum += __shfl_down_sync(mask, sum, offset, kDotWidth);
      }
      if (dot_lane == 0) {
        y[row] = tau * sum;
      }
    }
    __syncthreads();

    float local_dot = 0.0f;
    for (int index = tid; index < size; index += blockDim.x) {
      local_dot += v[index] * y[index];
    }
    const float dot = block_sum_leader(local_dot, reduction);
    if (tid == 0) {
      reduction[0] = dot * (-0.5f * tau);
    }
    __syncthreads();
    const float correction = reduction[0];
    for (int index = tid; index < size; index += blockDim.x) {
      y[index] += correction * v[index];
    }
    __syncthreads();

    const int update_lane = tid & 31;
    const int update_warp = tid >> 5;
    for (int update_row = update_warp; update_row < size;
         update_row += static_cast<int>(blockDim.x) / 32) {
      for (int update_col = update_lane; update_col <= update_row;
           update_col += 32) {
        matrix[batch_offset + (base + update_row) * n + base + update_col] -=
            v[update_row] * y[update_col] +
            y[update_row] * v[update_col];
      }
    }
    __syncthreads();

    for (int index = tid; index < size; index += blockDim.x) {
      matrix[batch_offset + (base + index) * n + column] = index == 0
          ? off_diagonal[vector_offset + column]
          : v[index];
    }
    __syncthreads();
  }

  if (tid == 0) {
    diagonal[vector_offset + n - 2] =
        matrix[batch_offset + (n - 2) * n + n - 2];
    diagonal[vector_offset + n - 1] =
        matrix[batch_offset + (n - 1) * n + n - 1];
    off_diagonal[vector_offset + n - 2] =
        matrix[batch_offset + (n - 1) * n + n - 2];
    off_diagonal[vector_offset + n - 1] = 0.0f;
    taus[vector_offset + n - 2] = 0.0f;
    taus[vector_offset + n - 1] = 0.0f;
  }
}

template <bool kPackedLower, int kDotWidth>
__global__ void reduce_global_to_tridiagonal(
    float* matrix, float* diagonal, float* off_diagonal, float* taus, int n) {
  extern __shared__ float shared[];
  float* v = shared;
  float* y = v + n;
  float* reduction = y + n;
  const int tid = static_cast<int>(threadIdx.x);
  const int matrix_size = kPackedLower ? n * (n + 1) / 2 : n * n;
  const int64_t batch_offset =
      static_cast<int64_t>(blockIdx.x) * matrix_size;
  const int64_t vector_offset = static_cast<int64_t>(blockIdx.x) * n;

  for (int column = 0; column < n - 2; ++column) {
    const int base = column + 1;
    const int size = n - base;
    float local_norm = 0.0f;
    for (int index = tid + 1; index < size; index += blockDim.x) {
      const float value = matrix[
          batch_offset + matrix_lower_index<kPackedLower>(
              base + index, column, n)];
      local_norm += value * value;
    }
    const float norm_sum = block_sum_leader(local_norm, reduction);

    if (tid == 0) {
      const float alpha = matrix[
          batch_offset + matrix_lower_index<kPackedLower>(base, column, n)];
      const float tail_norm = sqrtf(norm_sum);
      float beta = alpha;
      float tau = 0.0f;
      float inverse = 0.0f;
      if (tail_norm != 0.0f) {
        beta = -copysignf(hypotf(alpha, tail_norm), alpha);
        tau = (beta - alpha) / beta;
        inverse = 1.0f / (alpha - beta);
      }
      diagonal[vector_offset + column] =
          matrix[batch_offset + matrix_lower_index<kPackedLower>(
              column, column, n)];
      off_diagonal[vector_offset + column] = beta;
      taus[vector_offset + column] = tau;
      reduction[0] = tau;
      reduction[1] = inverse;
    }
    __syncthreads();

    const float tau = reduction[0];
    const float inverse = reduction[1];
    for (int index = tid; index < size; index += blockDim.x) {
      v[index] = index == 0
          ? 1.0f
          : matrix[batch_offset + matrix_lower_index<kPackedLower>(
                base + index, column, n)] * inverse;
    }
    __syncthreads();

    const int dot_group = tid / kDotWidth;
    const int dot_lane = tid & (kDotWidth - 1);
    for (int row = dot_group; row < size;
         row += static_cast<int>(blockDim.x) / kDotWidth) {
      float sum = 0.0f;
      for (int inner = dot_lane; inner < size; inner += kDotWidth) {
        const float element = row >= inner
            ? matrix[batch_offset + matrix_lower_index<kPackedLower>(
                  base + row, base + inner, n)]
            : matrix[batch_offset + matrix_lower_index<kPackedLower>(
                  base + inner, base + row, n)];
        sum += element * v[inner];
      }
      const unsigned int mask = __activemask();
      #pragma unroll
      for (int offset = kDotWidth / 2; offset > 0; offset >>= 1) {
        sum += __shfl_down_sync(mask, sum, offset, kDotWidth);
      }
      if (dot_lane == 0) {
        y[row] = tau * sum;
      }
    }
    __syncthreads();

    float local_dot = 0.0f;
    for (int index = tid; index < size; index += blockDim.x) {
      local_dot += v[index] * y[index];
    }
    const float dot = block_sum_leader(local_dot, reduction);
    if (tid == 0) {
      reduction[0] = dot * (-0.5f * tau);
    }
    __syncthreads();
    const float correction = reduction[0];
    for (int index = tid; index < size; index += blockDim.x) {
      y[index] += correction * v[index];
    }
    __syncthreads();

    const int update_lane = tid & 31;
    const int update_warp = tid >> 5;
    for (int update_row = update_warp; update_row < size;
         update_row += static_cast<int>(blockDim.x) / 32) {
      for (int update_col = update_lane; update_col <= update_row;
           update_col += 32) {
        matrix[batch_offset + matrix_lower_index<kPackedLower>(
            base + update_row, base + update_col, n)] -=
            v[update_row] * y[update_col] +
            y[update_row] * v[update_col];
      }
    }
    __syncthreads();

    for (int index = tid; index < size; index += blockDim.x) {
      matrix[batch_offset + matrix_lower_index<kPackedLower>(
          base + index, column, n)] = index == 0
          ? off_diagonal[vector_offset + column]
          : v[index];
    }
    __syncthreads();
  }

  if (tid == 0) {
    diagonal[vector_offset + n - 2] =
        matrix[batch_offset + matrix_lower_index<kPackedLower>(
            n - 2, n - 2, n)];
    diagonal[vector_offset + n - 1] =
        matrix[batch_offset + matrix_lower_index<kPackedLower>(
            n - 1, n - 1, n)];
    off_diagonal[vector_offset + n - 2] =
        matrix[batch_offset + matrix_lower_index<kPackedLower>(
            n - 1, n - 2, n)];
    off_diagonal[vector_offset + n - 1] = 0.0f;
    taus[vector_offset + n - 2] = 0.0f;
    taus[vector_offset + n - 1] = 0.0f;
  }
}

template <int kEigenpairsPerBlock, int kGroupWidth, int kVectorPitch,
          int kBisectionIterations, bool kColumnMajorReflectors,
          bool kBacktransform>
__global__ void tridiagonal_eigh_and_backtransform(
    const float* reflectors, const float* input_diagonal,
    const float* input_off_diagonal, const float* taus, float* vectors,
    float* values, int* info, int n) {
  constexpr int kThreads = kEigenpairsPerBlock * kGroupWidth;
  extern __shared__ float shared[];
  float* d = shared;
  float* e = d + n;
  float* tile_vectors = e + n;
  float* tile_factors = tile_vectors + n * kVectorPitch;
  __shared__ float lower_bounds[kThreads];
  __shared__ float upper_bounds[kThreads];

  const int tid = static_cast<int>(threadIdx.x);
  const int tiles_per_matrix = (n + kEigenpairsPerBlock - 1) /
      kEigenpairsPerBlock;
  const int matrix = static_cast<int>(blockIdx.x) / tiles_per_matrix;
  const int tile = static_cast<int>(blockIdx.x) % tiles_per_matrix;
  const int eigen_slot = tid / kGroupWidth;
  const int group_lane = tid & (kGroupWidth - 1);
  const int eigen_index = tile * kEigenpairsPerBlock + eigen_slot;
  const int64_t vector_offset = static_cast<int64_t>(matrix) * n;
  const int64_t matrix_offset = vector_offset * n;
  for (int index = tid; index < n; index += blockDim.x) {
    d[index] = input_diagonal[vector_offset + index];
    e[index] = input_off_diagonal[vector_offset + index];
  }
  __syncthreads();

  float local_low = FLT_MAX;
  float local_high = -FLT_MAX;
  for (int index = tid; index < n; index += blockDim.x) {
    const float radius = (index ? fabsf(e[index - 1]) : 0.0f) +
        (index + 1 < n ? fabsf(e[index]) : 0.0f);
    local_low = fminf(local_low, d[index] - radius);
    local_high = fmaxf(local_high, d[index] + radius);
  }
  lower_bounds[tid] = local_low;
  upper_bounds[tid] = local_high;
  __syncthreads();
  for (int stride = blockDim.x / 2; stride; stride >>= 1) {
    if (tid < stride) {
      lower_bounds[tid] = fminf(lower_bounds[tid], lower_bounds[tid + stride]);
      upper_bounds[tid] = fmaxf(upper_bounds[tid], upper_bounds[tid + stride]);
    }
    __syncthreads();
  }
  const float global_low = lower_bounds[0];
  const float global_high = upper_bounds[0];
  if (tid == 0 && tile == 0) {
    info[matrix] = 0;
  }

  if (eigen_index < n) {
    const unsigned int group_mask = __activemask();
    const float margin = 8.0f * FLT_EPSILON *
        (1.0f + fmaxf(fabsf(global_low), fabsf(global_high)));
    const float pivot_min = 1.0e-20f *
        (1.0f + global_high - global_low);
    if (group_lane == 0) {
      float low = global_low - margin;
      float high = global_high + margin;
      for (int iteration = 0; iteration < kBisectionIterations; ++iteration) {
        const float midpoint = 0.5f * (low + high);
        float pivot = d[0] - midpoint;
        if (fabsf(pivot) < pivot_min) {
          pivot = -pivot_min;
        }
        int count = pivot < 0.0f;
        for (int row = 1; row < n; ++row) {
          pivot = d[row] - midpoint - e[row - 1] * e[row - 1] / pivot;
          if (fabsf(pivot) < pivot_min) {
            pivot = -pivot_min;
          }
          count += pivot < 0.0f;
        }
        if (count <= eigen_index) {
          low = midpoint;
        } else {
          high = midpoint;
        }
      }
      const float eigenvalue = 0.5f * (low + high);
      lower_bounds[eigen_slot] = eigenvalue;
      values[vector_offset + eigen_index] = eigenvalue;
    }
    __syncwarp(group_mask);
    const float eigenvalue = lower_bounds[eigen_slot];

    float* factors = tile_factors + eigen_slot;
    float* eigenvector = tile_vectors + eigen_slot;
    if (group_lane == 0) {
      for (int row = 0; row < n; ++row) {
        const int pattern = (row * 17 + eigen_index * 13) % 23;
        eigenvector[row * kVectorPitch] =
            static_cast<float>(pattern - 11) / 11.0f;
      }
      const int inverse_iterations = n == 176 ? 3 : 2;
      for (int iteration = 0; iteration < inverse_iterations; ++iteration) {
        const float signed_shift = (iteration & 1) ? 1.0f : -1.0f;
        const float shifted_value = eigenvalue + signed_shift *
            2.0f * FLT_EPSILON * (1.0f + fabsf(eigenvalue));
        factors[0] = d[0] - shifted_value;
        if (fabsf(factors[0]) < pivot_min) {
          factors[0] = copysignf(pivot_min, factors[0]);
        }
        for (int row = 1; row < n; ++row) {
          const int factor_offset = row * kVectorPitch;
          const int vector_offset = row * kVectorPitch;
          const float multiplier =
              e[row - 1] /
              factors[factor_offset - kVectorPitch];
          factors[factor_offset] =
              d[row] - shifted_value - multiplier * e[row - 1];
          if (fabsf(factors[factor_offset]) < pivot_min) {
            factors[factor_offset] =
                copysignf(pivot_min, factors[factor_offset]);
          }
          eigenvector[vector_offset] -=
              multiplier * eigenvector[vector_offset - kVectorPitch];
        }
        eigenvector[(n - 1) * kVectorPitch] /=
            factors[(n - 1) * kVectorPitch];
        for (int row = n - 2; row >= 0; --row) {
          const int factor_offset = row * kVectorPitch;
          const int vector_offset = row * kVectorPitch;
          eigenvector[vector_offset] =
              (eigenvector[vector_offset] -
               e[row] * eigenvector[vector_offset + kVectorPitch]) /
              factors[factor_offset];
        }
        float norm = 0.0f;
        for (int row = 0; row < n; ++row) {
          const float value = eigenvector[row * kVectorPitch];
          norm += value * value;
        }
        const float inverse_norm = rsqrtf(norm);
        for (int row = 0; row < n; ++row) {
          eigenvector[row * kVectorPitch] *= inverse_norm;
        }
      }
    }
    __syncwarp(group_mask);

    if constexpr (kBacktransform) {
      for (int column = n - 3; column >= 0; --column) {
        const int base = column + 1;
        const int size = n - base;
        float partial = group_lane == 0
            ? eigenvector[base * kVectorPitch]
            : 0.0f;
        for (int row = group_lane + 1; row < size; row += kGroupWidth) {
          const int64_t reflector_index = kColumnMajorReflectors
              ? matrix_offset + column * n + base + row
              : matrix_offset + (base + row) * n + column;
          partial += reflectors[reflector_index] *
              eigenvector[(base + row) * kVectorPitch];
        }
        for (int offset = kGroupWidth / 2; offset > 0; offset >>= 1) {
          partial += __shfl_down_sync(group_mask, partial, offset, kGroupWidth);
        }
        const float dot = __shfl_sync(group_mask, partial, 0, kGroupWidth);
        const float tau = taus[vector_offset + column];
        const float scale = tau * dot;
        if (group_lane == 0) {
          eigenvector[base * kVectorPitch] -= scale;
        }
        for (int row = group_lane + 1; row < size; row += kGroupWidth) {
          const int64_t reflector_index = kColumnMajorReflectors
              ? matrix_offset + column * n + base + row
              : matrix_offset + (base + row) * n + column;
          eigenvector[(base + row) * kVectorPitch] -= scale *
              reflectors[reflector_index];
        }
        __syncwarp(group_mask);
      }
    }

    for (int row = group_lane; row < n; row += kGroupWidth) {
      vectors[matrix_offset + row * n + eigen_index] =
          eigenvector[row * kVectorPitch];
    }
  }
}

__global__ void certify_eigenpairs(
    const float* gram, const float* aq, const float* vectors,
    const float* values, int* flags, int batch, int n,
    int blocks_per_matrix) {
  extern __shared__ float value_maxima[];
  const int tid = static_cast<int>(threadIdx.x);
  const int matrix = static_cast<int>(blockIdx.x) / blocks_per_matrix;
  const int matrix_block = static_cast<int>(blockIdx.x) % blocks_per_matrix;
  if (matrix >= batch) {
    return;
  }

  const int64_t vector_offset = static_cast<int64_t>(matrix) * n;
  const int64_t matrix_offset = vector_offset * n;
  float local_maximum = 0.0f;
  for (int column = tid; column < n; column += blockDim.x) {
    local_maximum = fmaxf(
        local_maximum, fabsf(values[vector_offset + column]));
  }
  value_maxima[tid] = local_maximum;
  __syncthreads();
  for (int stride = blockDim.x / 2; stride; stride >>= 1) {
    if (tid < stride) {
      value_maxima[tid] = fmaxf(
          value_maxima[tid], value_maxima[tid + stride]);
    }
    __syncthreads();
  }

  const float value_scale = fmaxf(value_maxima[0], 1.0e-30f);
  const float safety_fraction = n == 512 ? 0.99f : 0.7f;
  const float orthogonal_limit =
      safety_fraction * 100.0f * n * FLT_EPSILON;
  const float eigen_limit =
      safety_fraction * 200.0f * n * FLT_EPSILON * value_scale;
  for (int column = matrix_block * blockDim.x + tid;
       column < n; column += blocks_per_matrix * blockDim.x) {
    float orthogonal_sum = 0.0f;
    float eigen_sum = 0.0f;
    const float eigenvalue = values[vector_offset + column];
    for (int row = 0; row < n; ++row) {
      const int64_t index = matrix_offset + row * n + column;
      const float orthogonal_residual =
          gram[index] - static_cast<float>(row == column);
      const float eigen_residual =
          aq[index] - vectors[index] * eigenvalue;
      orthogonal_sum += fabsf(orthogonal_residual);
      eigen_sum += fabsf(eigen_residual);
    }
    if (!isfinite(orthogonal_sum) || !isfinite(eigen_sum) ||
        orthogonal_sum > orthogonal_limit || eigen_sum > eigen_limit) {
      atomicExch(flags + matrix, 1);
      atomicExch(flags + batch, 1);
    }
  }
}

