__device__ __forceinline__ int packed_lower_index(int row, int column) {
  return (row * (row + 1)) / 2 + column;
}

__device__ __forceinline__ int packed_column_index(
    int row, int column, int n) {
  return column * n - (column * (column - 1)) / 2 + row - column;
}

__global__ void reduce_packed_to_tridiagonal(
    float* matrix, float* diagonal, float* off_diagonal, float* taus, int n) {
  extern __shared__ float shared[];
  float* v = shared;
  float* y = v + n;
  float* reduction = y + n;
  const int tid = static_cast<int>(threadIdx.x);
  const int packed_size = n * (n + 1) / 2;
  const int64_t batch_offset =
      static_cast<int64_t>(blockIdx.x) * packed_size;
  const int64_t vector_offset = static_cast<int64_t>(blockIdx.x) * n;

  for (int column = 0; column < n - 2; ++column) {
    const int base = column + 1;
    const int size = n - base;
    float local_norm = 0.0f;
    for (int index = tid + 1; index < size; index += blockDim.x) {
      const float value = matrix[
          batch_offset + packed_lower_index(base + index, column)];
      local_norm += value * value;
    }
    const float norm_sum = block_sum_leader(local_norm, reduction);

    if (tid == 0) {
      const float alpha =
          matrix[batch_offset + packed_lower_index(base, column)];
      const float tail_norm = sqrtf(norm_sum);
      float beta = alpha;
      float tau = 0.0f;
      float inverse = 0.0f;
      if (tail_norm != 0.0f) {
        beta = -copysignf(hypotf(alpha, tail_norm), alpha);
        tau = (beta - alpha) / beta;
        inverse = 1.0f / (alpha - beta);
      }
      diagonal[vector_offset + column] =
          matrix[batch_offset + packed_lower_index(column, column)];
      off_diagonal[vector_offset + column] = beta;
      taus[vector_offset + column] = tau;
      reduction[0] = tau;
      reduction[1] = inverse;
    }
    __syncthreads();

    const float tau = reduction[0];
    const float inverse = reduction[1];
    for (int index = tid; index < size; index += blockDim.x) {
      v[index] = index == 0
          ? 1.0f
          : matrix[batch_offset + packed_lower_index(base + index, column)] *
              inverse;
    }
    __syncthreads();

    constexpr int kDotWidth = 8;
    const int dot_group = tid / kDotWidth;
    const int dot_lane = tid & (kDotWidth - 1);
    for (int row = dot_group; row < size;
         row += static_cast<int>(blockDim.x) / kDotWidth) {
      float sum = 0.0f;
      for (int inner = dot_lane; inner < size; inner += kDotWidth) {
        const float element = row >= inner
            ? matrix[batch_offset +
                     packed_lower_index(base + row, base + inner)]
            : matrix[batch_offset +
                     packed_lower_index(base + inner, base + row)];
        sum += element * v[inner];
      }
      const unsigned int mask = __activemask();
      #pragma unroll
      for (int offset = kDotWidth / 2; offset > 0; offset >>= 1) {
        sum += __shfl_down_sync(mask, sum, offset, kDotWidth);
      }
      if (dot_lane == 0) {
        y[row] = tau * sum;
      }
    }
    __syncthreads();

    float local_dot = 0.0f;
    for (int index = tid; index < size; index += blockDim.x) {
      local_dot += v[index] * y[index];
    }
    const float dot = block_sum_leader(local_dot, reduction);
    if (tid == 0) {
      reduction[0] = dot * (-0.5f * tau);
    }
    __syncthreads();
    const float correction = reduction[0];
    for (int index = tid; index < size; index += blockDim.x) {
      y[index] += correction * v[index];
    }
    __syncthreads();

    const int update_lane = tid & 31;
    const int update_warp = tid >> 5;
    for (int update_row = update_warp; update_row < size;
         update_row += static_cast<int>(blockDim.x) / 32) {
      for (int update_col = update_lane; update_col <= update_row;
           update_col += 32) {
        matrix[batch_offset +
               packed_lower_index(base + update_row, base + update_col)] -=
            v[update_row] * y[update_col] +
            y[update_row] * v[update_col];
      }
    }
    __syncthreads();

    for (int index = tid; index < size; index += blockDim.x) {
      matrix[batch_offset + packed_lower_index(base + index, column)] =
          index == 0
          ? off_diagonal[vector_offset + column]
          : v[index];
    }
    __syncthreads();
  }

  if (tid == 0) {
    diagonal[vector_offset + n - 2] =
        matrix[batch_offset + packed_lower_index(n - 2, n - 2)];
    diagonal[vector_offset + n - 1] =
        matrix[batch_offset + packed_lower_index(n - 1, n - 1)];
    off_diagonal[vector_offset + n - 2] =
        matrix[batch_offset + packed_lower_index(n - 1, n - 2)];
    off_diagonal[vector_offset + n - 1] = 0.0f;
    taus[vector_offset + n - 2] = 0.0f;
    taus[vector_offset + n - 1] = 0.0f;
  }
}

template <int kBlocksPerMatrix, int kN>
__global__ void reduce_packed_clustered(
    const float* __restrict__ input, float* __restrict__ matrix,
    float* __restrict__ column_reflectors,
    float* __restrict__ diagonal, float* __restrict__ off_diagonal,
    float* __restrict__ taus) {
  constexpr int n = kN;
  extern __shared__ float local_shared[];
  float* local_v = local_shared;
  float* local_y = local_v + n;
  float* local_reduction = local_y + n;
  float* local_scalars = local_reduction + 32;
  int* local_rows = reinterpret_cast<int*>(local_scalars + 8);
  cg::cluster_group cluster = cg::this_cluster();
  const int tid = static_cast<int>(threadIdx.x);
  const int cta = static_cast<int>(cluster.block_rank());
  const int matrix_index = static_cast<int>(blockIdx.x) / kBlocksPerMatrix;
  const int cluster_tid = cta * static_cast<int>(blockDim.x) + tid;
  const int cluster_threads =
      kBlocksPerMatrix * static_cast<int>(blockDim.x);
  const int packed_size = n * (n + 1) / 2;
  const int64_t batch_offset =
      static_cast<int64_t>(matrix_index) * packed_size;
  const int64_t input_offset =
      static_cast<int64_t>(matrix_index) * n * n;
  const int64_t vector_offset = static_cast<int64_t>(matrix_index) * n;
  float* v = cluster.map_shared_rank(local_v, 0);
  float* y = cluster.map_shared_rank(local_y, 0);
  float* scalars = cluster.map_shared_rank(local_scalars, 0);

  for (int index = cluster_tid; index < packed_size;
       index += cluster_threads) {
    const int row = static_cast<int>(
        0.5f * (sqrtf(8.0f * static_cast<float>(index) + 1.0f) - 1.0f));
    const int column = index - packed_lower_index(row, 0);
    matrix[batch_offset + index] = input[input_offset + row * n + column];
  }
  for (int row = tid; row < n; row += blockDim.x) {
    local_rows[row] = row * (row + 1) / 2;
  }
  cluster.sync();

  constexpr int kClusterColumns = 32;
  for (int column = 0; column < kClusterColumns; ++column) {
    const int base = column + 1;
    const int size = n - base;
    if (cta == 0) {
      float local_norm = 0.0f;
      for (int index = tid + 1; index < size; index += blockDim.x) {
        const float value = matrix[
            batch_offset + local_rows[base + index] + column];
        local_norm += value * value;
      }
      const float norm_sum = block_sum_leader(local_norm, local_reduction);
      if (tid == 0) {
        const float alpha =
            matrix[batch_offset + local_rows[base] + column];
        const float tail_norm = sqrtf(norm_sum);
        float beta = alpha;
        float tau = 0.0f;
        float inverse = 0.0f;
        if (tail_norm != 0.0f) {
          beta = -copysignf(hypotf(alpha, tail_norm), alpha);
          tau = (beta - alpha) / beta;
          inverse = 1.0f / (alpha - beta);
        }
        diagonal[vector_offset + column] =
            matrix[batch_offset + local_rows[column] + column];
        off_diagonal[vector_offset + column] = beta;
        taus[vector_offset + column] = tau;
        scalars[0] = tau;
        scalars[1] = inverse;
      }
      __syncthreads();
      const float inverse = scalars[1];
      for (int index = tid; index < size; index += blockDim.x) {
        local_v[index] = index == 0
            ? 1.0f
            : matrix[
                  batch_offset + local_rows[base + index] + column] *
                inverse;
      }
    }
    cluster.sync();

    const float tau = scalars[0];
    constexpr int kDotWidth = 8;
    const int dot_group = cluster_tid / kDotWidth;
    const int dot_lane = cluster_tid & (kDotWidth - 1);
    float local_dot = 0.0f;
    for (int row = dot_group; row < size;
         row += cluster_threads / kDotWidth) {
      float sum = 0.0f;
      const int row_start = local_rows[base + row] + base;
      for (int inner = dot_lane; inner <= row; inner += kDotWidth) {
        sum += matrix[batch_offset + row_start + inner] * v[inner];
      }
      const int upper_offset =
          (dot_lane - ((row + 1) & (kDotWidth - 1)) + kDotWidth) &
          (kDotWidth - 1);
      for (int inner = row + 1 + upper_offset; inner < size;
           inner += kDotWidth) {
        sum += matrix[batch_offset +
                      local_rows[base + inner] + base + row] *
            v[inner];
      }
      const unsigned int mask = __activemask();
      #pragma unroll
      for (int offset = kDotWidth / 2; offset > 0; offset >>= 1) {
        sum += __shfl_down_sync(mask, sum, offset, kDotWidth);
      }
      if (dot_lane == 0) {
        const float y_value = tau * sum;
        y[row] = y_value;
        local_dot += v[row] * y_value;
      }
    }
    const float block_dot = block_sum_leader(local_dot, local_reduction);
    if (tid == 0) {
      scalars[2 + cta] = block_dot;
    }
    cluster.sync();

    float dot = 0.0f;
    #pragma unroll
    for (int block = 0; block < kBlocksPerMatrix; ++block) {
      dot += scalars[2 + block];
    }
    const float correction = dot * (-0.5f * tau);
    const int update_lane = tid & 31;
    const int cluster_warp = cluster_tid >> 5;
    const int cluster_warps = cluster_threads >> 5;
    for (int update_row = cluster_warp; update_row < size;
         update_row += cluster_warps) {
      const int row_start = local_rows[base + update_row] + base;
      const float row_y = y[update_row] + correction * v[update_row];
      for (int update_col = update_lane; update_col <= update_row;
           update_col += 32) {
        const float column_y = y[update_col] + correction * v[update_col];
        matrix[batch_offset + row_start + update_col] -=
            v[update_row] * column_y + row_y * v[update_col];
      }
    }
    for (int index = cluster_tid; index < size; index += cluster_threads) {
      const float stored =
          index == 0 ? off_diagonal[vector_offset + column] : v[index];
      matrix[batch_offset + local_rows[base + index] + column] = stored;
      column_reflectors[
          batch_offset + packed_column_index(base + index, column, n)] =
          stored;
    }
    cluster.sync();
  }

  if (cta != 0) {
    return;
  }
  for (int column = kClusterColumns; column < n - 2; ++column) {
    const int base = column + 1;
    const int size = n - base;
    float local_norm = 0.0f;
    for (int index = tid + 1; index < size; index += blockDim.x) {
      const float value = matrix[
          batch_offset + local_rows[base + index] + column];
      local_norm += value * value;
    }
    const float norm_sum = block_sum_leader(local_norm, local_reduction);
    if (tid == 0) {
      const float alpha =
          matrix[batch_offset + local_rows[base] + column];
      const float tail_norm = sqrtf(norm_sum);
      float beta = alpha;
      float tau = 0.0f;
      float inverse = 0.0f;
      if (tail_norm != 0.0f) {
        beta = -copysignf(hypotf(alpha, tail_norm), alpha);
        tau = (beta - alpha) / beta;
        inverse = 1.0f / (alpha - beta);
      }
      diagonal[vector_offset + column] =
          matrix[batch_offset + local_rows[column] + column];
      off_diagonal[vector_offset + column] = beta;
      taus[vector_offset + column] = tau;
      local_reduction[0] = tau;
      local_reduction[1] = inverse;
    }
    __syncthreads();

    const float tau = local_reduction[0];
    const float inverse = local_reduction[1];
    for (int index = tid; index < size; index += blockDim.x) {
      local_v[index] = index == 0
          ? 1.0f
          : matrix[batch_offset + local_rows[base + index] + column] *
              inverse;
    }
    __syncthreads();

    constexpr int kDotWidth = 8;
    const int dot_group = tid / kDotWidth;
    const int dot_lane = tid & (kDotWidth - 1);
    float local_dot = 0.0f;
    for (int row = dot_group; row < size;
         row += static_cast<int>(blockDim.x) / kDotWidth) {
      float sum = 0.0f;
      const int row_start = local_rows[base + row] + base;
      for (int inner = dot_lane; inner <= row; inner += kDotWidth) {
        sum += matrix[batch_offset + row_start + inner] * local_v[inner];
      }
      const int upper_offset =
          (dot_lane - ((row + 1) & (kDotWidth - 1)) + kDotWidth) &
          (kDotWidth - 1);
      for (int inner = row + 1 + upper_offset; inner < size;
           inner += kDotWidth) {
        sum += matrix[batch_offset +
                      local_rows[base + inner] + base + row] *
            local_v[inner];
      }
      const unsigned int mask = __activemask();
      #pragma unroll
      for (int offset = kDotWidth / 2; offset > 0; offset >>= 1) {
        sum += __shfl_down_sync(mask, sum, offset, kDotWidth);
      }
      if (dot_lane == 0) {
        const float y_value = tau * sum;
        local_y[row] = y_value;
        local_dot += local_v[row] * y_value;
      }
    }
    const float dot = block_sum_leader(local_dot, local_reduction);
    if (tid == 0) {
      local_reduction[0] = dot * (-0.5f * tau);
    }
    __syncthreads();

    const float correction = local_reduction[0];
    const int update_lane = tid & 31;
    const int update_warp = tid >> 5;
    const int update_warps = static_cast<int>(blockDim.x) >> 5;
    for (int update_row = update_warp; update_row < size;
         update_row += update_warps) {
      const int row_start = local_rows[base + update_row] + base;
      const float row_y =
          local_y[update_row] + correction * local_v[update_row];
      for (int update_col = update_lane; update_col <= update_row;
           update_col += 32) {
        const float column_y =
            local_y[update_col] + correction * local_v[update_col];
        matrix[batch_offset + row_start + update_col] -=
            local_v[update_row] * column_y + row_y * local_v[update_col];
      }
    }
    for (int index = tid; index < size; index += blockDim.x) {
      const float stored = index == 0
          ? off_diagonal[vector_offset + column]
          : local_v[index];
      matrix[batch_offset + local_rows[base + index] + column] = stored;
      column_reflectors[
          batch_offset + packed_column_index(base + index, column, n)] =
          stored;
    }
    __syncthreads();
  }

  if (cta == 0 && tid == 0) {
    diagonal[vector_offset + n - 2] =
        matrix[batch_offset + local_rows[n - 2] + n - 2];
    diagonal[vector_offset + n - 1] =
        matrix[batch_offset + local_rows[n - 1] + n - 1];
    off_diagonal[vector_offset + n - 2] =
        matrix[batch_offset + local_rows[n - 1] + n - 2];
    off_diagonal[vector_offset + n - 1] = 0.0f;
    taus[vector_offset + n - 2] = 0.0f;
    taus[vector_offset + n - 1] = 0.0f;
  }
}

template <int kEigenvaluesPerBlock, int kN>
__global__ void tridiagonal_eigenvalues(
    const float* __restrict__ input_diagonal,
    const float* __restrict__ input_off_diagonal,
    float* __restrict__ values, int* __restrict__ info) {
  constexpr int n = kN;
  extern __shared__ float shared[];
  float* d = shared;
  float* e = d + n;
  float* e_squared = e + n;
  __shared__ float lower_bounds[kEigenvaluesPerBlock];
  __shared__ float upper_bounds[kEigenvaluesPerBlock];

  const int tid = static_cast<int>(threadIdx.x);
  const int tiles_per_matrix =
      (n + kEigenvaluesPerBlock - 1) / kEigenvaluesPerBlock;
  const int matrix = static_cast<int>(blockIdx.x) / tiles_per_matrix;
  const int tile = static_cast<int>(blockIdx.x) % tiles_per_matrix;
  const int eigen_index = tile * kEigenvaluesPerBlock + tid;
  const int64_t vector_offset = static_cast<int64_t>(matrix) * n;
  for (int index = tid; index < n; index += blockDim.x) {
    d[index] = input_diagonal[vector_offset + index];
    e[index] = input_off_diagonal[vector_offset + index];
    e_squared[index] = e[index] * e[index];
  }
  __syncthreads();

  float local_low = FLT_MAX;
  float local_high = -FLT_MAX;
  for (int index = tid; index < n; index += blockDim.x) {
    const float radius = (index ? fabsf(e[index - 1]) : 0.0f) +
        (index + 1 < n ? fabsf(e[index]) : 0.0f);
    local_low = fminf(local_low, d[index] - radius);
    local_high = fmaxf(local_high, d[index] + radius);
  }
  lower_bounds[tid] = local_low;
  upper_bounds[tid] = local_high;
  __syncthreads();
  for (int stride = blockDim.x / 2; stride; stride >>= 1) {
    if (tid < stride) {
      lower_bounds[tid] = fminf(lower_bounds[tid], lower_bounds[tid + stride]);
      upper_bounds[tid] = fmaxf(upper_bounds[tid], upper_bounds[tid + stride]);
    }
    __syncthreads();
  }
  const float global_low = lower_bounds[0];
  const float global_high = upper_bounds[0];
  if (tid == 0 && tile == 0) {
    info[matrix] = 0;
  }

  if (eigen_index < n) {
    const float margin = 8.0f * FLT_EPSILON *
        (1.0f + fmaxf(fabsf(global_low), fabsf(global_high)));
    const float pivot_min = 1.0e-20f *
        (1.0f + global_high - global_low);
    float low = global_low - margin;
    float high = global_high + margin;
    const int bisection_iterations = n == 176 ? 21 : 24;
    for (int iteration = 0; iteration < bisection_iterations; ++iteration) {
      const float midpoint = 0.5f * (low + high);
      float pivot = d[0] - midpoint;
      if (fabsf(pivot) < pivot_min) {
        pivot = -pivot_min;
      }
      int count = pivot < 0.0f;
      for (int row = 1; row < n; ++row) {
        pivot = d[row] - midpoint - e_squared[row - 1] / pivot;
        if (fabsf(pivot) < pivot_min) {
          pivot = -pivot_min;
        }
        count += pivot < 0.0f;
      }
      if (count <= eigen_index) {
        low = midpoint;
      } else {
        high = midpoint;
      }
    }
    values[vector_offset + eigen_index] = 0.5f * (low + high);
  }
}

template <int kEigenpairsPerBlock, int kGroupWidth, int kVectorPitch,
          bool kColumnMajorReflectors, bool kPackedLowerReflectors = false>
__global__ void tridiagonal_inverse_and_backtransform(
    const float* reflectors, const float* input_diagonal,
    const float* input_off_diagonal, const float* taus, float* vectors,
    float* values, int* info, int n, bool separate_eigenvalues) {
  constexpr int kThreads = kEigenpairsPerBlock * kGroupWidth;
  extern __shared__ float shared[];
  float* d = shared;
  float* e = d + n;
  float* tile_vectors = e + n;
  float* tile_factors = tile_vectors + n * kVectorPitch;
  __shared__ float lower_bounds[kThreads];
  __shared__ float upper_bounds[kThreads];
  const int tid = static_cast<int>(threadIdx.x);
  const int tiles_per_matrix = (n + kEigenpairsPerBlock - 1) /
      kEigenpairsPerBlock;
  const int matrix = static_cast<int>(blockIdx.x) / tiles_per_matrix;
  const int tile = static_cast<int>(blockIdx.x) % tiles_per_matrix;
  const int eigen_slot = tid / kGroupWidth;
  const int group_lane = tid & (kGroupWidth - 1);
  const int eigen_index = tile * kEigenpairsPerBlock + eigen_slot;
  const int64_t vector_offset = static_cast<int64_t>(matrix) * n;
  const int64_t matrix_offset = vector_offset * n;
  const int64_t reflector_offset = kPackedLowerReflectors
      ? static_cast<int64_t>(matrix) * n * (n + 1) / 2
      : matrix_offset;
  for (int index = tid; index < n; index += blockDim.x) {
    d[index] = input_diagonal[vector_offset + index];
    e[index] = input_off_diagonal[vector_offset + index];
  }
  __syncthreads();

  float global_low = 0.0f;
  float global_high = 0.0f;
  if (!separate_eigenvalues) {
    float local_low = FLT_MAX;
    float local_high = -FLT_MAX;
    for (int index = tid; index < n; index += blockDim.x) {
      const float radius = (index ? fabsf(e[index - 1]) : 0.0f) +
          (index + 1 < n ? fabsf(e[index]) : 0.0f);
      local_low = fminf(local_low, d[index] - radius);
      local_high = fmaxf(local_high, d[index] + radius);
    }
    lower_bounds[tid] = local_low;
    upper_bounds[tid] = local_high;
    __syncthreads();
    for (int stride = blockDim.x / 2; stride; stride >>= 1) {
      if (tid < stride) {
        lower_bounds[tid] =
            fminf(lower_bounds[tid], lower_bounds[tid + stride]);
        upper_bounds[tid] =
            fmaxf(upper_bounds[tid], upper_bounds[tid + stride]);
      }
      __syncthreads();
    }
    global_low = lower_bounds[0];
    global_high = upper_bounds[0];
    if (tid == 0 && tile == 0) {
      info[matrix] = 0;
    }
  }

  if (eigen_index < n) {
    const unsigned int group_mask = __activemask();
    float eigenvalue = 0.0f;
    float pivot_min = 0.0f;
    if (separate_eigenvalues) {
      eigenvalue = values[vector_offset + eigen_index];
      pivot_min = 1.0e-20f * (1.0f + fabsf(eigenvalue));
    } else {
      const float margin = 8.0f * FLT_EPSILON *
          (1.0f + fmaxf(fabsf(global_low), fabsf(global_high)));
      pivot_min = 1.0e-20f * (1.0f + global_high - global_low);
      if (group_lane == 0) {
        float low = global_low - margin;
        float high = global_high + margin;
        const int bisection_iterations = n == 176 ? 21 : 24;
        for (int iteration = 0; iteration < bisection_iterations; ++iteration) {
          const float midpoint = 0.5f * (low + high);
          float pivot = d[0] - midpoint;
          if (fabsf(pivot) < pivot_min) {
            pivot = -pivot_min;
          }
          int count = pivot < 0.0f;
          for (int row = 1; row < n; ++row) {
            pivot = d[row] - midpoint - e[row - 1] * e[row - 1] / pivot;
            if (fabsf(pivot) < pivot_min) {
              pivot = -pivot_min;
            }
            count += pivot < 0.0f;
          }
          if (count <= eigen_index) {
            low = midpoint;
          } else {
            high = midpoint;
          }
        }
        lower_bounds[eigen_slot] = 0.5f * (low + high);
        values[vector_offset + eigen_index] = lower_bounds[eigen_slot];
      }
      __syncwarp(group_mask);
      eigenvalue = lower_bounds[eigen_slot];
    }

    float* factors = tile_factors + eigen_slot;
    float* eigenvector = tile_vectors + eigen_slot;
    if (group_lane == 0) {
      for (int row = 0; row < n; ++row) {
        const int pattern = (row * 17 + eigen_index * 13) % 23;
        eigenvector[row * kVectorPitch] =
            static_cast<float>(pattern - 11) / 11.0f;
      }
      const int inverse_iterations = n == 176 ? 3 : 2;
      for (int iteration = 0; iteration < inverse_iterations; ++iteration) {
        const float signed_shift = (iteration & 1) ? 1.0f : -1.0f;
        const float shifted_value = eigenvalue + signed_shift *
            2.0f * FLT_EPSILON * (1.0f + fabsf(eigenvalue));
        factors[0] = d[0] - shifted_value;
        if (fabsf(factors[0]) < pivot_min) {
          factors[0] = copysignf(pivot_min, factors[0]);
        }
        for (int row = 1; row < n; ++row) {
          const int factor_offset = row * kVectorPitch;
          const int vector_offset = row * kVectorPitch;
          const float multiplier =
              e[row - 1] /
              factors[factor_offset - kVectorPitch];
          factors[factor_offset] =
              d[row] - shifted_value - multiplier * e[row - 1];
          if (fabsf(factors[factor_offset]) < pivot_min) {
            factors[factor_offset] =
                copysignf(pivot_min, factors[factor_offset]);
          }
          eigenvector[vector_offset] -=
              multiplier * eigenvector[vector_offset - kVectorPitch];
        }
        eigenvector[(n - 1) * kVectorPitch] /=
            factors[(n - 1) * kVectorPitch];
        for (int row = n - 2; row >= 0; --row) {
          const int factor_offset = row * kVectorPitch;
          const int vector_offset = row * kVectorPitch;
          eigenvector[vector_offset] =
              (eigenvector[vector_offset] -
               e[row] * eigenvector[vector_offset + kVectorPitch]) /
              factors[factor_offset];
        }
        float norm = 0.0f;
        for (int row = 0; row < n; ++row) {
          const float value = eigenvector[row * kVectorPitch];
          norm += value * value;
        }
        const float inverse_norm = rsqrtf(norm);
        for (int row = 0; row < n; ++row) {
          eigenvector[row * kVectorPitch] *= inverse_norm;
        }
      }
    }
    __syncwarp(group_mask);

    for (int column = n - 3; column >= 0; --column) {
      const int base = column + 1;
      const int size = n - base;
      float partial = group_lane == 0
          ? eigenvector[base * kVectorPitch]
          : 0.0f;
      for (int row = group_lane + 1; row < size; row += kGroupWidth) {
        const int64_t reflector_index = kColumnMajorReflectors
            ? reflector_offset + column * n + base + row
            : (kPackedLowerReflectors
                ? reflector_offset + packed_lower_index(base + row, column)
                : reflector_offset + (base + row) * n + column);
        partial += reflectors[reflector_index] *
            eigenvector[(base + row) * kVectorPitch];
      }
      for (int offset = kGroupWidth / 2; offset > 0; offset >>= 1) {
        partial += __shfl_down_sync(group_mask, partial, offset, kGroupWidth);
      }
      const float dot = __shfl_sync(group_mask, partial, 0, kGroupWidth);
      const float tau = taus[vector_offset + column];
      const float scale = tau * dot;
      if (group_lane == 0) {
        eigenvector[base * kVectorPitch] -= scale;
      }
      for (int row = group_lane + 1; row < size; row += kGroupWidth) {
        const int64_t reflector_index = kColumnMajorReflectors
            ? reflector_offset + column * n + base + row
            : (kPackedLowerReflectors
                ? reflector_offset + packed_lower_index(base + row, column)
                : reflector_offset + (base + row) * n + column);
        eigenvector[(base + row) * kVectorPitch] -= scale *
            reflectors[reflector_index];
      }
      __syncwarp(group_mask);
    }

    for (int row = group_lane; row < n; row += kGroupWidth) {
      vectors[matrix_offset + row * n + eigen_index] =
          eigenvector[row * kVectorPitch];
    }
  }
}

template <int kEigenpairsPerBlock, int kVectorPitch, int kN>
__global__ void tridiagonal_inverse_iteration(
    const float* __restrict__ input_diagonal,
    const float* __restrict__ input_off_diagonal,
    const float* __restrict__ values, float* __restrict__ vectors) {
  constexpr int n = kN;
  extern __shared__ float shared[];
  float* d = shared;
  float* e = d + n;
  float* tile_vectors = e + n;
  float* tile_factors = tile_vectors + n * kVectorPitch;

  const int tid = static_cast<int>(threadIdx.x);
  const int tiles_per_matrix = (n + kEigenpairsPerBlock - 1) /
      kEigenpairsPerBlock;
  const int matrix = static_cast<int>(blockIdx.x) / tiles_per_matrix;
  const int tile = static_cast<int>(blockIdx.x) % tiles_per_matrix;
  const int eigen_index = tile * kEigenpairsPerBlock + tid;
  const int64_t vector_offset = static_cast<int64_t>(matrix) * n;
  const int64_t matrix_offset = vector_offset * n;
  for (int index = tid; index < n; index += blockDim.x) {
    d[index] = input_diagonal[vector_offset + index];
    e[index] = input_off_diagonal[vector_offset + index];
  }
  __syncthreads();

  if (eigen_index < n) {
    const float eigenvalue = values[vector_offset + eigen_index];
    const float pivot_min = 1.0e-20f * (1.0f + fabsf(eigenvalue));
    float* factors = tile_factors + tid;
    float* eigenvector = tile_vectors + tid;
    for (int row = 0; row < n; ++row) {
      const int pattern = (row * 17 + eigen_index * 13) % 23;
      eigenvector[row * kVectorPitch] =
          static_cast<float>(pattern - 11) / 11.0f;
    }
    for (int iteration = 0; iteration < 2; ++iteration) {
      const float signed_shift = (iteration & 1) ? 1.0f : -1.0f;
      const float shifted_value = eigenvalue + signed_shift *
          2.0f * FLT_EPSILON * (1.0f + fabsf(eigenvalue));
      factors[0] = d[0] - shifted_value;
      if (fabsf(factors[0]) < pivot_min) {
        factors[0] = copysignf(pivot_min, factors[0]);
      }
      for (int row = 1; row < n; ++row) {
        const int row_offset = row * kVectorPitch;
        const float multiplier =
            e[row - 1] / factors[row_offset - kVectorPitch];
        factors[row_offset] =
            d[row] - shifted_value - multiplier * e[row - 1];
        if (fabsf(factors[row_offset]) < pivot_min) {
          factors[row_offset] = copysignf(pivot_min, factors[row_offset]);
        }
        eigenvector[row_offset] -=
            multiplier * eigenvector[row_offset - kVectorPitch];
      }
      eigenvector[(n - 1) * kVectorPitch] /=
          factors[(n - 1) * kVectorPitch];
      for (int row = n - 2; row >= 0; --row) {
        const int row_offset = row * kVectorPitch;
        eigenvector[row_offset] =
            (eigenvector[row_offset] -
             e[row] * eigenvector[row_offset + kVectorPitch]) /
            factors[row_offset];
      }
      float norm = 0.0f;
      for (int row = 0; row < n; ++row) {
        const float value = eigenvector[row * kVectorPitch];
        norm += value * value;
      }
      const float inverse_norm = rsqrtf(norm);
      for (int row = 0; row < n; ++row) {
        eigenvector[row * kVectorPitch] *= inverse_norm;
      }
    }
    for (int row = 0; row < n; ++row) {
      vectors[matrix_offset + row * n + eigen_index] =
          eigenvector[row * kVectorPitch];
    }
  }
}

template <int kN>
__global__ void reflector_pair_couplings(
    const float* __restrict__ reflectors,
    float* __restrict__ couplings) {
  constexpr int n = kN;
  const int matrix = static_cast<int>(blockIdx.x);
  const int lane = static_cast<int>(threadIdx.x) & 31;
  const int warp = static_cast<int>(threadIdx.x) >> 5;
  const int warps = static_cast<int>(blockDim.x) >> 5;
  const int packed_size = n * (n + 1) / 2;
  const int64_t reflector_offset =
      static_cast<int64_t>(matrix) * packed_size;
  const int64_t vector_offset = static_cast<int64_t>(matrix) * n;
  for (int pair = warp; 2 * pair + 1 <= n - 3; pair += warps) {
    const int column = 2 * pair + 1;
    const int previous_column = column - 1;
    const int current_offset = packed_column_index(column, column, n);
    const int previous_offset =
        packed_column_index(previous_column, previous_column, n);
    float coupling = lane == 0
        ? reflectors[reflector_offset + previous_offset + 2]
        : 0.0f;
    for (int row = column + 2 + lane; row < n; row += 32) {
      coupling +=
          reflectors[reflector_offset + previous_offset + row -
                     previous_column] *
          reflectors[reflector_offset + current_offset + row - column];
    }
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
      coupling += __shfl_down_sync(0xffffffffu, coupling, offset);
    }
    if (lane == 0) {
      couplings[vector_offset + column] = coupling;
    }
  }
}

template <int kEigenpairsPerBlock, int kGroupWidth, int kVectorPitch, int kN>
__global__ void packed_reflector_backtransform(
    const float* __restrict__ reflectors,
    const float* __restrict__ taus,
    const float* __restrict__ couplings,
    float* __restrict__ vectors) {
  constexpr int n = kN;
  extern __shared__ float tile_vectors[];
  const int tid = static_cast<int>(threadIdx.x);
  const int tiles_per_matrix = (n + kEigenpairsPerBlock - 1) /
      kEigenpairsPerBlock;
  const int matrix = static_cast<int>(blockIdx.x) / tiles_per_matrix;
  const int tile = static_cast<int>(blockIdx.x) % tiles_per_matrix;
  const int eigen_slot = tid / kGroupWidth;
  const int group_lane = tid & (kGroupWidth - 1);
  const int eigen_index = tile * kEigenpairsPerBlock + eigen_slot;
  const int64_t vector_offset = static_cast<int64_t>(matrix) * n;
  const int64_t matrix_offset = vector_offset * n;
  const int64_t reflector_offset =
      static_cast<int64_t>(matrix) * n * (n + 1) / 2;

  for (int index = tid; index < n * kEigenpairsPerBlock;
       index += blockDim.x) {
    const int row = index / kEigenpairsPerBlock;
    const int slot = index - row * kEigenpairsPerBlock;
    const int column = tile * kEigenpairsPerBlock + slot;
    if (column < n) {
      tile_vectors[row * kVectorPitch + slot] =
          vectors[matrix_offset + row * n + column];
    }
  }
  __syncthreads();

  if (eigen_index < n) {
    const unsigned int group_mask = __activemask();
    float* eigenvector = tile_vectors + eigen_slot;
    for (int column = n - 3; column >= 1; column -= 2) {
      const int previous_column = column - 1;
      const int current_base = column + 1;
      const int current_offset = packed_column_index(column, column, n);
      const int previous_offset =
          packed_column_index(previous_column, previous_column, n);
      const float previous_at_current_base =
          reflectors[reflector_offset + previous_offset + 2];
      float current_partial = group_lane == 0
          ? eigenvector[current_base * kVectorPitch]
          : 0.0f;
      float previous_partial = group_lane == 0
          ? eigenvector[column * kVectorPitch] +
              previous_at_current_base *
                  eigenvector[current_base * kVectorPitch]
          : 0.0f;
      int current_index = current_offset + group_lane + 2;
      int previous_index = previous_offset + group_lane + 3;
      for (int row = current_base + group_lane + 1; row < n;
           row += kGroupWidth) {
        const float value = eigenvector[row * kVectorPitch];
        current_partial +=
            reflectors[reflector_offset + current_index] * value;
        previous_partial +=
            reflectors[reflector_offset + previous_index] * value;
        current_index += kGroupWidth;
        previous_index += kGroupWidth;
      }
      for (int offset = kGroupWidth / 2; offset > 0; offset >>= 1) {
        current_partial += __shfl_down_sync(
            group_mask, current_partial, offset, kGroupWidth);
        previous_partial += __shfl_down_sync(
            group_mask, previous_partial, offset, kGroupWidth);
      }
      const float current_scale = taus[vector_offset + column] *
          __shfl_sync(group_mask, current_partial, 0, kGroupWidth);
      const float previous_dot =
          __shfl_sync(group_mask, previous_partial, 0, kGroupWidth) -
          current_scale * couplings[vector_offset + column];
      const float previous_scale =
          taus[vector_offset + previous_column] * previous_dot;
      if (group_lane == 0) {
        eigenvector[column * kVectorPitch] -= previous_scale;
        eigenvector[current_base * kVectorPitch] -=
            current_scale + previous_scale * previous_at_current_base;
      }
      current_index = current_offset + group_lane + 2;
      previous_index = previous_offset + group_lane + 3;
      for (int row = current_base + group_lane + 1; row < n;
           row += kGroupWidth) {
        eigenvector[row * kVectorPitch] -=
            current_scale * reflectors[reflector_offset + current_index] +
            previous_scale * reflectors[reflector_offset + previous_index];
        current_index += kGroupWidth;
        previous_index += kGroupWidth;
      }
    }
    for (int row = group_lane; row < n; row += kGroupWidth) {
      vectors[matrix_offset + row * n + eigen_index] =
          eigenvector[row * kVectorPitch];
    }
  }
}

__global__ void certify_eigenpairs(
    const float* gram, const float* aq, const float* vectors,
    const float* values, int* flags, int batch, int n,
    int blocks_per_matrix) {
  extern __shared__ float value_maxima[];
  const int tid = static_cast<int>(threadIdx.x);
  const int matrix = static_cast<int>(blockIdx.x) / blocks_per_matrix;
  const int matrix_block = static_cast<int>(blockIdx.x) % blocks_per_matrix;
  if (matrix >= batch) {
    return;
  }

  const int64_t vector_offset = static_cast<int64_t>(matrix) * n;
  const int64_t matrix_offset = vector_offset * n;
  float local_maximum = 0.0f;
  for (int column = tid; column < n; column += blockDim.x) {
    local_maximum = fmaxf(
        local_maximum, fabsf(values[vector_offset + column]));
  }
  value_maxima[tid] = local_maximum;
  __syncthreads();
  for (int stride = blockDim.x / 2; stride; stride >>= 1) {
    if (tid < stride) {
      value_maxima[tid] = fmaxf(
          value_maxima[tid], value_maxima[tid + stride]);
    }
    __syncthreads();
  }

  const float value_scale = fmaxf(value_maxima[0], 1.0e-30f);
  const float orthogonal_limit = 0.7f * 100.0f * n * FLT_EPSILON;
  const float eigen_limit =
      0.7f * 200.0f * n * FLT_EPSILON * value_scale;
  for (int column = matrix_block * blockDim.x + tid;
       column < n; column += blocks_per_matrix * blockDim.x) {
    float orthogonal_sum = 0.0f;
    float eigen_sum = 0.0f;
    const float eigenvalue = values[vector_offset + column];
    for (int row = 0; row < n; ++row) {
      const int64_t index = matrix_offset + row * n + column;
      const float orthogonal_residual =
          gram[index] - static_cast<float>(row == column);
      const float eigen_residual =
          aq[index] - vectors[index] * eigenvalue;
      orthogonal_sum += fabsf(orthogonal_residual);
      eigen_sum += fabsf(eigen_residual);
    }
    if (!isfinite(orthogonal_sum) || !isfinite(eigen_sum) ||
        orthogonal_sum > orthogonal_limit || eigen_sum > eigen_limit) {
      atomicExch(flags + matrix, 1);
      atomicExch(flags + batch, 1);
    }
  }
}

