std::vector<torch::Tensor> band_eigh(torch::Tensor input) {
  TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
  TORCH_CHECK(input.scalar_type() == torch::kFloat32, "input must be FP32");
  TORCH_CHECK(input.dim() == 3 && input.size(1) == input.size(2),
              "input must have shape [batch, n, n]");
  const c10::cuda::CUDAGuard device_guard(input.device());
  const int batch = static_cast<int>(input.size(0));
  const int n = static_cast<int>(input.size(1));
  TORCH_CHECK(n == 176 || n == 352,
              "custom band eigensolver supports n=176 or n=352");

  const int packed_size = n * (n + 1) / 2;
  auto reflectors = n == 176
      ? torch::empty_like(input)
      : torch::empty({batch, packed_size}, input.options());
  auto vectors = torch::empty_like(input);
  auto values = torch::empty({batch, n}, input.options());
  auto diagonal = torch::empty({batch, n}, input.options());
  auto off_diagonal = torch::empty({batch, n}, input.options());
  auto taus = torch::empty({batch, n}, input.options());
  auto info = torch::zeros({batch}, input.options().dtype(torch::kInt32));

  if (n == 176) {
    const int reduce_shared = (n * (n + 4) + 2 * n + 256) * sizeof(float);
    const int solve_shared = (2 * n + 2 * n * 16) * sizeof(float);
    cudaFuncSetAttribute(reduce_band_to_tridiagonal,
                         cudaFuncAttributeMaxDynamicSharedMemorySize,
                         reduce_shared);
    cudaFuncSetAttribute(
        tridiagonal_inverse_and_backtransform<16, 8, 16, true>,
        cudaFuncAttributeMaxDynamicSharedMemorySize, solve_shared);
    reduce_band_to_tridiagonal<<<batch, 1024, reduce_shared>>>(
        input.data_ptr<float>(), reflectors.data_ptr<float>(),
        diagonal.data_ptr<float>(), off_diagonal.data_ptr<float>(),
        taus.data_ptr<float>(), n);
    tridiagonal_inverse_and_backtransform<16, 8, 16, true><<<
        batch * 11, 128, solve_shared>>>(
        reflectors.data_ptr<float>(), diagonal.data_ptr<float>(),
        off_diagonal.data_ptr<float>(), taus.data_ptr<float>(),
        vectors.data_ptr<float>(), values.data_ptr<float>(), info.data_ptr<int>(),
        n, false);
  } else {
    auto column_reflectors =
        torch::empty({batch, packed_size}, input.options());
    auto reflector_couplings = torch::empty({batch, n}, input.options());
    const int reduce_shared = (2 * n + 32) * sizeof(float);
    const int solve_shared = (2 * n + 2 * n * 33) * sizeof(float);
    constexpr int kInversePairs = 64;
    constexpr int kInversePitch = 65;
    constexpr int kBacktransformPairs = 32;
    constexpr int kBacktransformLanes = 16;
    constexpr int kBacktransformPitch = 34;
    const int inverse_shared =
        (2 * n + 2 * n * kInversePitch) * sizeof(float);
    const int backtransform_shared =
        n * kBacktransformPitch * sizeof(float);
    cudaFuncSetAttribute(
        tridiagonal_inverse_iteration<kInversePairs, kInversePitch, 352>,
        cudaFuncAttributeMaxDynamicSharedMemorySize, inverse_shared);
    cudaFuncSetAttribute(
        packed_reflector_backtransform<
            kBacktransformPairs, kBacktransformLanes, kBacktransformPitch,
            352>,
        cudaFuncAttributeMaxDynamicSharedMemorySize, backtransform_shared);
    constexpr int kReducerBlocks = 2;
    cudaLaunchConfig_t config = {};
    config.gridDim = dim3(batch * kReducerBlocks, 1, 1);
    config.blockDim = dim3(1024, 1, 1);
    config.dynamicSmemBytes = (3 * n + 40) * sizeof(float);
    cudaLaunchAttribute attribute = {};
    attribute.id = cudaLaunchAttributeClusterDimension;
    attribute.val.clusterDim.x = kReducerBlocks;
    attribute.val.clusterDim.y = 1;
    attribute.val.clusterDim.z = 1;
    config.attrs = &attribute;
    config.numAttrs = 1;
    const cudaError_t launch_status = cudaLaunchKernelEx(
        &config, reduce_packed_clustered<kReducerBlocks, 352>,
        input.data_ptr<float>(), reflectors.data_ptr<float>(),
        column_reflectors.data_ptr<float>(),
        diagonal.data_ptr<float>(),
        off_diagonal.data_ptr<float>(), taus.data_ptr<float>());
    TORCH_CHECK(launch_status == cudaSuccess,
                "clustered reducer launch failed: ",
                cudaGetErrorString(launch_status));
    reflector_pair_couplings<352><<<batch, 1024>>>(
        column_reflectors.data_ptr<float>(),
        reflector_couplings.data_ptr<float>());
    tridiagonal_eigenvalues<128, 352><<<
        batch * 3, 128, 3 * n * sizeof(float)>>>(
        diagonal.data_ptr<float>(), off_diagonal.data_ptr<float>(),
        values.data_ptr<float>(), info.data_ptr<int>());
    tridiagonal_inverse_iteration<kInversePairs, kInversePitch, 352><<<
        batch * 6, kInversePairs, inverse_shared>>>(
        diagonal.data_ptr<float>(), off_diagonal.data_ptr<float>(),
        values.data_ptr<float>(), vectors.data_ptr<float>());
    packed_reflector_backtransform<
        kBacktransformPairs, kBacktransformLanes, kBacktransformPitch, 352><<<
        batch * 11, kBacktransformPairs * kBacktransformLanes,
        backtransform_shared>>>(
        column_reflectors.data_ptr<float>(), taus.data_ptr<float>(),
        reflector_couplings.data_ptr<float>(), vectors.data_ptr<float>());
  }
  return {vectors, values};
}

