torch::Tensor certify_eigh(
    torch::Tensor input, torch::Tensor vectors, torch::Tensor values) {
  TORCH_CHECK(input.is_cuda() && vectors.is_cuda() && values.is_cuda(),
              "certificate inputs must be CUDA tensors");
  TORCH_CHECK(input.scalar_type() == torch::kFloat32 &&
              vectors.scalar_type() == torch::kFloat32 &&
              values.scalar_type() == torch::kFloat32,
              "certificate inputs must be FP32");
  TORCH_CHECK(input.is_contiguous() && vectors.is_contiguous() &&
              values.is_contiguous(), "certificate inputs must be contiguous");
  const c10::cuda::CUDAGuard device_guard(input.device());
  const int batch = static_cast<int>(input.size(0));
  const int n = static_cast<int>(input.size(1));
  CertificateState& state = certificate_state();
  if (state.device != input.get_device() ||
      state.batch != batch || state.n != n) {
    state.device = input.get_device();
    state.batch = batch;
    state.n = n;
    state.gram = torch::empty_like(input);
    state.aq = torch::empty_like(input);
    state.flags = torch::empty(
        {batch + 1}, input.options().dtype(torch::kInt32));
  }
  state.flags.zero_();
  at::bmm_out(state.gram, vectors.transpose(1, 2), vectors);
  at::bmm_out(state.aq, input, vectors);
  const int certificate_threads = n > 256 ? 128 : 256;
  const int certificate_blocks =
      (n + certificate_threads - 1) / certificate_threads;
  certify_eigenpairs<<<
      batch * certificate_blocks, certificate_threads,
      certificate_threads * sizeof(float)>>>(
      state.gram.data_ptr<float>(), state.aq.data_ptr<float>(),
      vectors.data_ptr<float>(), values.data_ptr<float>(),
      state.flags.data_ptr<int>(), batch, n,
      certificate_blocks);
  return state.flags;
}

