__global__ void reduce_global_to_tridiagonal_dense(
    float* matrix, float* diagonal, float* off_diagonal, float* taus, int n) {
  extern __shared__ float shared[];
  float* v = shared;
  float* y = v + n;
  float* reduction = y + n;
  const int tid = static_cast<int>(threadIdx.x);
  const int64_t batch_offset = static_cast<int64_t>(blockIdx.x) * n * n;
  const int64_t vector_offset = static_cast<int64_t>(blockIdx.x) * n;

  for (int column = 0; column < n - 2; ++column) {
    const int base = column + 1;
    const int size = n - base;
    float local_norm = 0.0f;
    for (int index = tid + 1; index < size; index += blockDim.x) {
      const float value = matrix[batch_offset + (base + index) * n + column];
      local_norm += value * value;
    }
    const float norm_sum = block_sum_leader(local_norm, reduction);

    if (tid == 0) {
      const float alpha = matrix[batch_offset + base * n + column];
      const float tail_norm = sqrtf(norm_sum);
      float beta = alpha;
      float tau = 0.0f;
      float inverse = 0.0f;
      if (tail_norm != 0.0f) {
        beta = -copysignf(hypotf(alpha, tail_norm), alpha);
        tau = (beta - alpha) / beta;
        inverse = 1.0f / (alpha - beta);
      }
      diagonal[vector_offset + column] =
          matrix[batch_offset + column * n + column];
      off_diagonal[vector_offset + column] = beta;
      taus[vector_offset + column] = tau;
      reduction[0] = tau;
      reduction[1] = inverse;
    }
    __syncthreads();

    const float tau = reduction[0];
    const float inverse = reduction[1];
    for (int index = tid; index < size; index += blockDim.x) {
      v[index] = index == 0
          ? 1.0f
          : matrix[batch_offset + (base + index) * n + column] * inverse;
    }
    __syncthreads();

    constexpr int kDotWidth = 8;
    const int dot_group = tid / kDotWidth;
    const int dot_lane = tid & (kDotWidth - 1);
    for (int row = dot_group; row < size;
         row += static_cast<int>(blockDim.x) / kDotWidth) {
      float sum = 0.0f;
      for (int inner = dot_lane; inner < size; inner += kDotWidth) {
        const float element = row >= inner
            ? matrix[batch_offset + (base + row) * n + base + inner]
            : matrix[batch_offset + (base + inner) * n + base + row];
        sum += element * v[inner];
      }
      const unsigned int mask = __activemask();
      #pragma unroll
      for (int offset = kDotWidth / 2; offset > 0; offset >>= 1) {
        sum += __shfl_down_sync(mask, sum, offset, kDotWidth);
      }
      if (dot_lane == 0) {
        y[row] = tau * sum;
      }
    }
    __syncthreads();

    float local_dot = 0.0f;
    for (int index = tid; index < size; index += blockDim.x) {
      local_dot += v[index] * y[index];
    }
    const float dot = block_sum_leader(local_dot, reduction);
    if (tid == 0) {
      reduction[0] = dot * (-0.5f * tau);
    }
    __syncthreads();
    const float correction = reduction[0];
    for (int index = tid; index < size; index += blockDim.x) {
      y[index] += correction * v[index];
    }
    __syncthreads();

    const int update_lane = tid & 31;
    const int update_warp = tid >> 5;
    for (int update_row = update_warp; update_row < size;
         update_row += static_cast<int>(blockDim.x) / 32) {
      for (int update_col = update_lane; update_col <= update_row;
           update_col += 32) {
        matrix[batch_offset + (base + update_row) * n + base + update_col] -=
            v[update_row] * y[update_col] +
            y[update_row] * v[update_col];
      }
    }
    __syncthreads();

    for (int index = tid; index < size; index += blockDim.x) {
      matrix[batch_offset + (base + index) * n + column] = index == 0
          ? off_diagonal[vector_offset + column]
          : v[index];
    }
    __syncthreads();
  }

  if (tid == 0) {
    diagonal[vector_offset + n - 2] =
        matrix[batch_offset + (n - 2) * n + n - 2];
    diagonal[vector_offset + n - 1] =
        matrix[batch_offset + (n - 1) * n + n - 1];
    off_diagonal[vector_offset + n - 2] =
        matrix[batch_offset + (n - 1) * n + n - 2];
    off_diagonal[vector_offset + n - 1] = 0.0f;
    taus[vector_offset + n - 2] = 0.0f;
    taus[vector_offset + n - 1] = 0.0f;
  }
}

